(function(w){w.HOMEWORK_SET_DATA=w.HOMEWORK_SET_DATA||{};w.HOMEWORK_SET_DATA["unit31-trap-c4-basic-5"]={"id":"unit31-trap-c4-basic-5","unitId":"3-1","chapterIds":["3-1"],"unitType":"basic","group":"3-1단원 · 선지 변형 유형 · 비교","name":"기본 OX 5","level":"기본","revision":3,"resetReviewOnRevision":true,"originPage":"unit31","shuffleQuestions":true,"timedMode":"question","isTypePractice":true,"practiceMode":"trap","practiceCategory":"비교","parts":[{"name":"U31-H09-05-B2 · 현대인과 프롬의 생각","items":[{"paragraphCount":1,"readingLabel":"9문단 · 핵심 읽기 5/5단계","sourceLabel":"에리히 프롬의 『사랑의 기술』 읽기 · 9문단","passage":"[문단 전체 · 9문단]\n프롬은 현대인이 사랑에 대해서 배울 필요가 없다고 생각하는 이유를 위와 같은 세 가지의 태도로 정리한다. 그러나 프롬은 사랑이 흔히 말하듯 즐겁고 흥분된 감정이 아니라 끊임없이 연마해야 하는 기술이라고 말한다. 어떤 기술을 익히기 위해서는 그 기술에 대해서 이론적으로 배우고 실습해야 한다. 사랑의 기술 역시 그것을 익히기 위해서는 성숙한 사랑이 무엇인지, 그리고 그러한 진정한 사랑을 하기 위해서는 어떻게 해야 하는지를 배우고 그대로 실천해야 한다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit31","skills":["비교"],"why":"프롬은 사랑도 배우고 실천해야 하는 기술이라고 말한다.\n근거: “프롬은 현대인이 사랑에 대해서 배울 필요가 없다고 생각하는 이유를 위와 같은 세 가지의 태도로 정리한다.” “그러나 프롬은 사랑이 흔히 말하듯 즐겁고 흥분된 감정이 아니라 끊임없이 연마해야 하는 기술이라고 말한다.”","evidence":{"title":"현대인과 프롬의 생각","statement":"프롬은 사랑을 배울 필요가 없다는 현대인의 생각에 반대한다.","explanation":"프롬은 사랑도 배우고 실천해야 하는 기술이라고 말한다.\n근거: “프롬은 현대인이 사랑에 대해서 배울 필요가 없다고 생각하는 이유를 위와 같은 세 가지의 태도로 정리한다.” “그러나 프롬은 사랑이 흔히 말하듯 즐겁고 흥분된 감정이 아니라 끊임없이 연마해야 하는 기술이라고 말한다.”","valid":["R09:1","R09:2"],"sources":[{"id":"R09","title":"에리히 프롬의 『사랑의 기술』 읽기","label":"9문단","sentences":[{"id":"R09:1","text":"프롬은 현대인이 사랑에 대해서 배울 필요가 없다고 생각하는 이유를 위와 같은 세 가지의 태도로 정리한다.","paragraph":0,"memberIds":["R09:1"],"topic":"프롬은 현대인이 사랑을 배울 필요가 없다고 생각하는 이유를, 앞의 세 가지 태도로 정리한다."},{"id":"R09:2","text":"그러나 프롬은 사랑이 흔히 말하듯 즐겁고 흥분된 감정이 아니라 끊임없이 연마해야 하는 기술이라고 말한다.","paragraph":0,"memberIds":["R09:2"],"topic":"그러나 프롬은 이렇게 말한다. 사랑은 흔히 말하는 것처럼 즐겁고 들뜬 감정이 아니다. 끊임없이 갈고닦아야(연마해야) 하는 기술이다."},{"id":"R09:3","text":"어떤 기술을 익히기 위해서는 그 기술에 대해서 이론적으로 배우고 실습해야 한다.","paragraph":0,"memberIds":["R09:3"],"topic":"어떤 기술이든 익히려면 그 기술을 이론으로 배우고, 직접 해 보며 연습해야(실습해야) 한다."},{"id":"R09:4","text":"사랑의 기술 역시 그것을 익히기 위해서는 성숙한 사랑이 무엇인지, 그리고 그러한 진정한 사랑을 하기 위해서는 어떻게 해야 하는지를 배우고 그대로 실천해야 한다.","paragraph":0,"memberIds":["R09:4"],"topic":"사랑의 기술도 마찬가지다. 익히려면 성숙한 사랑이 무엇인지, 그런 진짜 사랑을 하려면 어떻게 해야 하는지를 배워야 한다. 그리고 배운 그대로 실천해야 한다."}]}]},"shortComparison":true,"focusQuotes":[{"id":"R09:1","text":"프롬은 현대인이 사랑에 대해서 배울 필요가 없다고 생각하는 이유를 위와 같은 세 가지의 태도로 정리한다."},{"id":"R09:2","text":"그러나 프롬은 사랑이 흔히 말하듯 즐겁고 흥분된 감정이 아니라 끊임없이 연마해야 하는 기술이라고 말한다."}],"highlightEvidence":true,"requiresEvidence":false,"id":"U31-H09-05-B2","type":"ox","answer":"X","changed":"프롬은 사랑을 배울 필요가 없다는 현대인의 생각에 동의한다.","ask":"다음 설명이 이 문단의 중요한 내용과 같으면 O, 다르면 X를 고르세요.","claimEdits":[{"start":28,"end":33,"before":"동의한다.","after":"반대한다."}],"progressiveComparison":true,"progressiveStep":5,"progressiveTotal":5,"progressiveLabel":"핵심 의미 확인","learningFocus":"현대인과 프롬의 생각","hintGuide":"현대인의 생각과 프롬의 생각이 같은지 비교하세요.","synthesis":true,"editorSourceVersion":"c7733b2ea192b0508c0411aa8573ef5a8f5cc52e7b1eb434bfa5399d7eb51e7b"}]},{"name":"U31-E01-B1 · 비교","items":[{"paragraphCount":2,"readingLabel":"5문단 · 새 예시 적용","sourceLabel":"에리히 프롬의 『사랑의 기술』 읽기 · 5문단","passage":"[에리히 프롬의 『사랑의 기술』 읽기 · 5문단]\n첫째로 현대인은 연인 간 사랑의 문제를 다른 사람을 어떻게 사랑할 것인가라는 문제로 보지 않고, 멋진 사람에게서 어떻게 하면 사랑을 받을 수 있는가라는 문제로 본다. 따라서 현대인은 자신을 사랑받을 만한 존재로 만들기 위해서 다시 말해 최대한 매력적으로 보이기 위해서 온갖 노력을 다한다. 사람들이 자신을 매력적인 사람으로 보이기 위해 주로 사용하는 방법은 부자가 되거나 고위직에 올라가는 것, 아름다운 외모를 갖는 것, 유머를 구사하고 흥미 있게 대화를 끌어가는 것, 모나지 않고 모든 사람과 원만하게 지내는 것 등이다.\n\n[이해를 돕는 새 예시 · 원문 사례 아님]\n서진과 민준은 팀에 도움을 주는 것보다 축구화와 개인기 영상으로 인기를 얻는 데만 몰두한다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit31","skills":["비교"],"why":"두 선수는 팀에 도움을 주기보다 인기를 얻는 데 집중한다. 현대인도 상대를 어떻게 사랑할지보다 자신이 어떻게 사랑받을지를 더 고민한다.\n근거: “첫째로 현대인은 연인 간 사랑의 문제를 다른 사람을 어떻게 사랑할 것인가라는 문제로 보지 않고, 멋진 사람에게서 어떻게 하면 사랑을 받을 수 있는가라는 문제로 본다.” “따라서 현대인은 자신을 사랑받을 만한 존재로 만들기 위해서 다시 말해 최대한 매력적으로 보이기 위해서 온갖 노력을 다한다.”\n5문단에서 확인할 수 있어요.","evidence":{"title":"인기만 얻으려는 선수","statement":"두 선수는 남에게 사랑받으려고 자신을 매력적으로 꾸미는 현대인과 닮았다.","explanation":"두 선수는 팀에 도움을 주기보다 인기를 얻는 데 집중한다. 현대인도 상대를 어떻게 사랑할지보다 자신이 어떻게 사랑받을지를 더 고민한다.\n근거: “첫째로 현대인은 연인 간 사랑의 문제를 다른 사람을 어떻게 사랑할 것인가라는 문제로 보지 않고, 멋진 사람에게서 어떻게 하면 사랑을 받을 수 있는가라는 문제로 본다.” “따라서 현대인은 자신을 사랑받을 만한 존재로 만들기 위해서 다시 말해 최대한 매력적으로 보이기 위해서 온갖 노력을 다한다.”\n5문단에서 확인할 수 있어요.","valid":["R05:1","R05:2"],"sources":[{"id":"R05","title":"에리히 프롬의 『사랑의 기술』 읽기","label":"5문단","sentences":[{"id":"R05:1","text":"첫째로 현대인은 연인 간 사랑의 문제를 다른 사람을 어떻게 사랑할 것인가라는 문제로 보지 않고, 멋진 사람에게서 어떻게 하면 사랑을 받을 수 있는가라는 문제로 본다.","paragraph":0,"memberIds":["R05:1"],"topic":"첫째, 현대인은 연인 사이의 사랑을 '내가 상대를 어떻게 사랑할까'의 문제로 보지 않는다. '멋진 사람에게 어떻게 하면 사랑받을까'의 문제로 본다."},{"id":"R05:2","text":"따라서 현대인은 자신을 사랑받을 만한 존재로 만들기 위해서 다시 말해 최대한 매력적으로 보이기 위해서 온갖 노력을 다한다.","paragraph":0,"memberIds":["R05:2"],"topic":"그래서 현대인은 사랑받을 만한 사람이 되려고, 다시 말해 최대한 매력 있어 보이려고 온갖 노력을 다한다."},{"id":"R05:3","text":"사람들이 자신을 매력적인 사람으로 보이기 위해 주로 사용하는 방법은 부자가 되거나 고위직에 올라가는 것, 아름다운 외모를 갖는 것, 유머를 구사하고 흥미 있게 대화를 끌어가는 것, 모나지 않고 모든 사람과 원만하게 지내는 것 등이다.","paragraph":0,"memberIds":["R05:3"],"topic":"매력 있어 보이려고 사람들이 주로 쓰는 방법은 이렇다. 부자가 되거나 높은 자리(고위직)에 오르기, 아름다운 외모 갖기, 유머를 쓰고 대화를 재미있게 이끌기, 모나지 않게 모두와 사이좋게 지내기."}]}]},"examplePractice":true,"id":"U31-E01-B1","type":"ox","answer":"O","changed":"두 선수는 남에게 사랑받으려고 자신을 매력적으로 꾸미는 현대인과 닮았다.","ask":"다음 설명이 지문과 새 예시에 맞으면 O, 다르면 X를 고르세요.","highlightEvidence":true,"requiresEvidence":false,"editorSourceVersion":"235fb6cec7cbd3a76578708c55cfcc1e9d0207b4374ef48dd512531ad0945ab5"}]},{"name":"U31-E01-B2 · 비교","items":[{"paragraphCount":2,"readingLabel":"5문단 · 새 예시 적용","sourceLabel":"에리히 프롬의 『사랑의 기술』 읽기 · 5문단","passage":"[에리히 프롬의 『사랑의 기술』 읽기 · 5문단]\n첫째로 현대인은 연인 간 사랑의 문제를 다른 사람을 어떻게 사랑할 것인가라는 문제로 보지 않고, 멋진 사람에게서 어떻게 하면 사랑을 받을 수 있는가라는 문제로 본다. 따라서 현대인은 자신을 사랑받을 만한 존재로 만들기 위해서 다시 말해 최대한 매력적으로 보이기 위해서 온갖 노력을 다한다. 사람들이 자신을 매력적인 사람으로 보이기 위해 주로 사용하는 방법은 부자가 되거나 고위직에 올라가는 것, 아름다운 외모를 갖는 것, 유머를 구사하고 흥미 있게 대화를 끌어가는 것, 모나지 않고 모든 사람과 원만하게 지내는 것 등이다.\n\n[이해를 돕는 새 예시 · 원문 사례 아님]\n서진과 민준은 팀에 도움을 주는 것보다 축구화와 개인기 영상으로 인기를 얻는 데만 몰두한다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit31","skills":["비교"],"why":"두 선수는 팀에 도움을 주기보다 인기를 얻는 데 집중한다. 현대인도 상대를 어떻게 사랑할지보다 자신이 어떻게 사랑받을지를 더 고민한다.\n근거: “첫째로 현대인은 연인 간 사랑의 문제를 다른 사람을 어떻게 사랑할 것인가라는 문제로 보지 않고, 멋진 사람에게서 어떻게 하면 사랑을 받을 수 있는가라는 문제로 본다.” “따라서 현대인은 자신을 사랑받을 만한 존재로 만들기 위해서 다시 말해 최대한 매력적으로 보이기 위해서 온갖 노력을 다한다.”\n5문단에서 확인할 수 있어요.","evidence":{"title":"인기만 얻으려는 선수","statement":"두 선수는 남에게 사랑받으려고 자신을 매력적으로 꾸미는 현대인과 닮았다.","explanation":"두 선수는 팀에 도움을 주기보다 인기를 얻는 데 집중한다. 현대인도 상대를 어떻게 사랑할지보다 자신이 어떻게 사랑받을지를 더 고민한다.\n근거: “첫째로 현대인은 연인 간 사랑의 문제를 다른 사람을 어떻게 사랑할 것인가라는 문제로 보지 않고, 멋진 사람에게서 어떻게 하면 사랑을 받을 수 있는가라는 문제로 본다.” “따라서 현대인은 자신을 사랑받을 만한 존재로 만들기 위해서 다시 말해 최대한 매력적으로 보이기 위해서 온갖 노력을 다한다.”\n5문단에서 확인할 수 있어요.","valid":["R05:1","R05:2"],"sources":[{"id":"R05","title":"에리히 프롬의 『사랑의 기술』 읽기","label":"5문단","sentences":[{"id":"R05:1","text":"첫째로 현대인은 연인 간 사랑의 문제를 다른 사람을 어떻게 사랑할 것인가라는 문제로 보지 않고, 멋진 사람에게서 어떻게 하면 사랑을 받을 수 있는가라는 문제로 본다.","paragraph":0,"memberIds":["R05:1"],"topic":"첫째, 현대인은 연인 사이의 사랑을 '내가 상대를 어떻게 사랑할까'의 문제로 보지 않는다. '멋진 사람에게 어떻게 하면 사랑받을까'의 문제로 본다."},{"id":"R05:2","text":"따라서 현대인은 자신을 사랑받을 만한 존재로 만들기 위해서 다시 말해 최대한 매력적으로 보이기 위해서 온갖 노력을 다한다.","paragraph":0,"memberIds":["R05:2"],"topic":"그래서 현대인은 사랑받을 만한 사람이 되려고, 다시 말해 최대한 매력 있어 보이려고 온갖 노력을 다한다."},{"id":"R05:3","text":"사람들이 자신을 매력적인 사람으로 보이기 위해 주로 사용하는 방법은 부자가 되거나 고위직에 올라가는 것, 아름다운 외모를 갖는 것, 유머를 구사하고 흥미 있게 대화를 끌어가는 것, 모나지 않고 모든 사람과 원만하게 지내는 것 등이다.","paragraph":0,"memberIds":["R05:3"],"topic":"매력 있어 보이려고 사람들이 주로 쓰는 방법은 이렇다. 부자가 되거나 높은 자리(고위직)에 오르기, 아름다운 외모 갖기, 유머를 쓰고 대화를 재미있게 이끌기, 모나지 않게 모두와 사이좋게 지내기."}]}]},"examplePractice":true,"id":"U31-E01-B2","type":"ox","answer":"X","changed":"두 선수는 다른 사람을 사랑하는 능력을 기르려고 연습하는 현대인과 닮았다.","ask":"다음 설명이 지문과 새 예시에 맞으면 O, 다르면 X를 고르세요.","highlightEvidence":true,"requiresEvidence":false,"claimEdits":[{"start":6,"end":32,"before":"다른 사람을 사랑하는 능력을 기르려고 연습하는 ","after":"남에게 사랑받으려고 자신을 매력적으로 꾸미는 "}],"editorSourceVersion":"e63487ef6e0f4c731757cf1093a2e7762d8ae898e7c678022ca377991bd2c223"}]},{"name":"U31-E02-B1 · 비교","items":[{"paragraphCount":2,"readingLabel":"6문단 · 새 예시 적용","sourceLabel":"에리히 프롬의 『사랑의 기술』 읽기 · 6문단","passage":"[에리히 프롬의 『사랑의 기술』 읽기 · 6문단]\n둘째로 현대인은 다른 사람을 사랑한다는 것을 지극히 쉬운 일로 생각한다. 사랑할 만한 대상, 즉 우리를 매료시키는 사람을 발견하는 것이 어렵지, 그런 사람만 발견하면 사랑이란 감정은 저절로 따라온다고 생각하는 것이다. 그래서 현대인은 사랑의 문제를 사랑하는 능력을 어떻게 육성할 것인가라는 문제로 보지 않고, 자신이 사랑하고 자신에게 사랑을 줄 올바른 상대를 어떻게 발견할 것인가라는 문제로 본다. 현대인은 사랑하는 방법을 배우거나 사랑하는 능력을 육성할 필요가 없다고 생각한다. 그 시간에 차라리 사랑할 만한 사람을 찾아다니는 것이 더 낫다고 보는 것이다.\n\n[이해를 돕는 새 예시 · 원문 사례 아님]\n하준은 좋은 팀만 만나면 저절로 잘할 것이라 여기며 훈련 대신 팀을 찾아다닌다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit31","skills":["비교"],"why":"하준은 훈련보다 좋은 팀을 찾는 일을 중요하게 생각한다. 현대인도 사랑하는 능력을 기르기보다 사랑할 상대를 찾는 일을 중요하게 생각한다.\n근거: “사랑할 만한 대상, 즉 우리를 매료시키는 사람을 발견하는 것이 어렵지, 그런 사람만 발견하면 사랑이란 감정은 저절로 따라온다고 생각하는 것이다.” “그래서 현대인은 사랑의 문제를 사랑하는 능력을 어떻게 육성할 것인가라는 문제로 보지 않고, 자신이 사랑하고 자신에게 사랑을 줄 올바른 상대를 어떻게 발견할 것인가라는 문제로 본다.” “현대인은 사랑하는 방법을 배우거나 사랑하는 능력을 육성할 필요가 없다고 생각한다.” “그 시간에 차라리 사랑할 만한 사람을 찾아다니는 것이 더 낫다고 보는 것이다.”\n6문단에서 확인할 수 있어요.","evidence":{"title":"팀만 찾아다니는 선수","statement":"하준은 자기 능력을 기르기보다 좋은 팀을 찾는 데 집중한다. 현대인이 좋은 상대를 찾는 데 집중하는 모습과 닮았다.","explanation":"하준은 훈련보다 좋은 팀을 찾는 일을 중요하게 생각한다. 현대인도 사랑하는 능력을 기르기보다 사랑할 상대를 찾는 일을 중요하게 생각한다.\n근거: “사랑할 만한 대상, 즉 우리를 매료시키는 사람을 발견하는 것이 어렵지, 그런 사람만 발견하면 사랑이란 감정은 저절로 따라온다고 생각하는 것이다.” “그래서 현대인은 사랑의 문제를 사랑하는 능력을 어떻게 육성할 것인가라는 문제로 보지 않고, 자신이 사랑하고 자신에게 사랑을 줄 올바른 상대를 어떻게 발견할 것인가라는 문제로 본다.” “현대인은 사랑하는 방법을 배우거나 사랑하는 능력을 육성할 필요가 없다고 생각한다.” “그 시간에 차라리 사랑할 만한 사람을 찾아다니는 것이 더 낫다고 보는 것이다.”\n6문단에서 확인할 수 있어요.","valid":["R06:2","R06:3","R06:4","R06:5"],"sources":[{"id":"R06","title":"에리히 프롬의 『사랑의 기술』 읽기","label":"6문단","sentences":[{"id":"R06:1","text":"둘째로 현대인은 다른 사람을 사랑한다는 것을 지극히 쉬운 일로 생각한다.","paragraph":0,"memberIds":["R06:1"],"topic":"둘째, 현대인은 다른 사람을 사랑하는 일을 아주 쉬운 일로 생각한다."},{"id":"R06:2","text":"사랑할 만한 대상, 즉 우리를 매료시키는 사람을 발견하는 것이 어렵지, 그런 사람만 발견하면 사랑이란 감정은 저절로 따라온다고 생각하는 것이다.","paragraph":0,"memberIds":["R06:2"],"topic":"어려운 건 사랑할 만한 사람, 곧 내 마음을 사로잡는(매료시키는) 사람을 찾는 일뿐이라고 생각한다. 그런 사람만 찾으면 사랑하는 마음은 저절로 생긴다는 것이다."},{"id":"R06:3","text":"그래서 현대인은 사랑의 문제를 사랑하는 능력을 어떻게 육성할 것인가라는 문제로 보지 않고, 자신이 사랑하고 자신에게 사랑을 줄 올바른 상대를 어떻게 발견할 것인가라는 문제로 본다.","paragraph":0,"memberIds":["R06:3"],"topic":"그래서 현대인은 사랑을 '사랑하는 능력을 어떻게 기를까(육성)'의 문제로 보지 않는다. '내가 사랑하고 나를 사랑해 줄 딱 맞는 상대를 어떻게 찾을까(발견)'의 문제로 본다."},{"id":"R06:4","text":"현대인은 사랑하는 방법을 배우거나 사랑하는 능력을 육성할 필요가 없다고 생각한다.","paragraph":0,"memberIds":["R06:4"],"topic":"현대인은 사랑하는 방법을 배울 필요도, 사랑하는 능력을 기를 필요도 없다고 생각한다."},{"id":"R06:5","text":"그 시간에 차라리 사랑할 만한 사람을 찾아다니는 것이 더 낫다고 보는 것이다.","paragraph":0,"memberIds":["R06:5"],"topic":"그럴 시간에 차라리 사랑할 만한 사람을 찾아다니는 게 더 낫다고 보는 것이다."}]}]},"examplePractice":true,"id":"U31-E02-B1","type":"ox","answer":"O","changed":"하준은 자기 능력을 기르기보다 좋은 팀을 찾는 데 집중한다. 현대인이 좋은 상대를 찾는 데 집중하는 모습과 닮았다.","ask":"다음 설명이 지문과 새 예시에 맞으면 O, 다르면 X를 고르세요.","highlightEvidence":true,"requiresEvidence":false,"editorSourceVersion":"223b7d728949c6687855f27e5cc356a9890982f384e5c45df7f8ec148ba9dcea"}]},{"name":"U31-E02-B2 · 비교","items":[{"paragraphCount":2,"readingLabel":"6문단 · 새 예시 적용","sourceLabel":"에리히 프롬의 『사랑의 기술』 읽기 · 6문단","passage":"[에리히 프롬의 『사랑의 기술』 읽기 · 6문단]\n둘째로 현대인은 다른 사람을 사랑한다는 것을 지극히 쉬운 일로 생각한다. 사랑할 만한 대상, 즉 우리를 매료시키는 사람을 발견하는 것이 어렵지, 그런 사람만 발견하면 사랑이란 감정은 저절로 따라온다고 생각하는 것이다. 그래서 현대인은 사랑의 문제를 사랑하는 능력을 어떻게 육성할 것인가라는 문제로 보지 않고, 자신이 사랑하고 자신에게 사랑을 줄 올바른 상대를 어떻게 발견할 것인가라는 문제로 본다. 현대인은 사랑하는 방법을 배우거나 사랑하는 능력을 육성할 필요가 없다고 생각한다. 그 시간에 차라리 사랑할 만한 사람을 찾아다니는 것이 더 낫다고 보는 것이다.\n\n[이해를 돕는 새 예시 · 원문 사례 아님]\n하준은 좋은 팀만 만나면 저절로 잘할 것이라 여기며 훈련 대신 팀을 찾아다닌다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit31","skills":["비교"],"why":"하준은 훈련보다 좋은 팀을 찾는 일을 중요하게 생각한다. 현대인도 사랑하는 능력을 기르기보다 사랑할 상대를 찾는 일을 중요하게 생각한다.\n근거: “사랑할 만한 대상, 즉 우리를 매료시키는 사람을 발견하는 것이 어렵지, 그런 사람만 발견하면 사랑이란 감정은 저절로 따라온다고 생각하는 것이다.” “그래서 현대인은 사랑의 문제를 사랑하는 능력을 어떻게 육성할 것인가라는 문제로 보지 않고, 자신이 사랑하고 자신에게 사랑을 줄 올바른 상대를 어떻게 발견할 것인가라는 문제로 본다.” “현대인은 사랑하는 방법을 배우거나 사랑하는 능력을 육성할 필요가 없다고 생각한다.” “그 시간에 차라리 사랑할 만한 사람을 찾아다니는 것이 더 낫다고 보는 것이다.”\n6문단에서 확인할 수 있어요.","evidence":{"title":"팀만 찾아다니는 선수","statement":"하준은 자기 능력을 기르기보다 좋은 팀을 찾는 데 집중한다. 현대인이 좋은 상대를 찾는 데 집중하는 모습과 닮았다.","explanation":"하준은 훈련보다 좋은 팀을 찾는 일을 중요하게 생각한다. 현대인도 사랑하는 능력을 기르기보다 사랑할 상대를 찾는 일을 중요하게 생각한다.\n근거: “사랑할 만한 대상, 즉 우리를 매료시키는 사람을 발견하는 것이 어렵지, 그런 사람만 발견하면 사랑이란 감정은 저절로 따라온다고 생각하는 것이다.” “그래서 현대인은 사랑의 문제를 사랑하는 능력을 어떻게 육성할 것인가라는 문제로 보지 않고, 자신이 사랑하고 자신에게 사랑을 줄 올바른 상대를 어떻게 발견할 것인가라는 문제로 본다.” “현대인은 사랑하는 방법을 배우거나 사랑하는 능력을 육성할 필요가 없다고 생각한다.” “그 시간에 차라리 사랑할 만한 사람을 찾아다니는 것이 더 낫다고 보는 것이다.”\n6문단에서 확인할 수 있어요.","valid":["R06:2","R06:3","R06:4","R06:5"],"sources":[{"id":"R06","title":"에리히 프롬의 『사랑의 기술』 읽기","label":"6문단","sentences":[{"id":"R06:1","text":"둘째로 현대인은 다른 사람을 사랑한다는 것을 지극히 쉬운 일로 생각한다.","paragraph":0,"memberIds":["R06:1"],"topic":"둘째, 현대인은 다른 사람을 사랑하는 일을 아주 쉬운 일로 생각한다."},{"id":"R06:2","text":"사랑할 만한 대상, 즉 우리를 매료시키는 사람을 발견하는 것이 어렵지, 그런 사람만 발견하면 사랑이란 감정은 저절로 따라온다고 생각하는 것이다.","paragraph":0,"memberIds":["R06:2"],"topic":"어려운 건 사랑할 만한 사람, 곧 내 마음을 사로잡는(매료시키는) 사람을 찾는 일뿐이라고 생각한다. 그런 사람만 찾으면 사랑하는 마음은 저절로 생긴다는 것이다."},{"id":"R06:3","text":"그래서 현대인은 사랑의 문제를 사랑하는 능력을 어떻게 육성할 것인가라는 문제로 보지 않고, 자신이 사랑하고 자신에게 사랑을 줄 올바른 상대를 어떻게 발견할 것인가라는 문제로 본다.","paragraph":0,"memberIds":["R06:3"],"topic":"그래서 현대인은 사랑을 '사랑하는 능력을 어떻게 기를까(육성)'의 문제로 보지 않는다. '내가 사랑하고 나를 사랑해 줄 딱 맞는 상대를 어떻게 찾을까(발견)'의 문제로 본다."},{"id":"R06:4","text":"현대인은 사랑하는 방법을 배우거나 사랑하는 능력을 육성할 필요가 없다고 생각한다.","paragraph":0,"memberIds":["R06:4"],"topic":"현대인은 사랑하는 방법을 배울 필요도, 사랑하는 능력을 기를 필요도 없다고 생각한다."},{"id":"R06:5","text":"그 시간에 차라리 사랑할 만한 사람을 찾아다니는 것이 더 낫다고 보는 것이다.","paragraph":0,"memberIds":["R06:5"],"topic":"그럴 시간에 차라리 사랑할 만한 사람을 찾아다니는 게 더 낫다고 보는 것이다."}]}]},"examplePractice":true,"id":"U31-E02-B2","type":"ox","answer":"X","changed":"하준은 좋은 팀을 찾기보다 자기 능력을 기르는 데 집중한다. 현대인이 좋은 상대를 찾는 데 집중하는 모습과 다르다.","ask":"다음 설명이 지문과 새 예시에 맞으면 O, 다르면 X를 고르세요.","highlightEvidence":true,"requiresEvidence":false,"claimEdits":[{"start":0,"end":4,"before":"하준은 ","after":"하준은 자기 능력을 기르기보다 "},{"start":10,"end":26,"before":"찾기보다 자기 능력을 기르는 ","after":"찾는 "},{"start":60,"end":64,"before":"다르다.","after":"닮았다."}],"editorSourceVersion":"15c16a5b4d7de759be50a9486d863080b5365b1200907bb70045eeb7cb5bfd5f"}]},{"name":"U31-E03-B1 · 비교","items":[{"paragraphCount":2,"readingLabel":"8문단 · 새 예시 적용","sourceLabel":"에리히 프롬의 『사랑의 기술』 읽기 · 8문단","passage":"[에리히 프롬의 『사랑의 기술』 읽기 · 8문단]\n셋째로 현대인은 멋진 상대를 만나 그에게 빠지는 것이 곧 사랑이라고 생각하기 때문에, 사랑에 처음 빠지는 순간 경험하는 격정적인 상태와 사랑이 지속되는 상태를 혼동한다. 두 연인 사이에 있던 벽이 갑자기 허물어지면서 두 사람이 완전히 하나가 된 것처럼 느끼는 상태야말로 우리가 맛볼 수 있는 가장 황홀한 기분이다. 그러나 이런 사랑은 오래 지속될 수 없다. 두 사람이 서로에 대해서 더 깊이 알게 될수록, 처음에 기적처럼 생겼던 친밀감은 갈수록 약화된다. 시쳇말로 눈에서 콩깍지가 벗겨지면서 처음에 느꼈던 기대와 설렘 그리고 즐거움 대신에, 서로에 대한 실망과 환멸 그리고 권태감이 자리하게 된다.\n\n[이해를 돕는 새 예시 · 원문 사례 아님]\n하준은 입단 첫날의 설렘을 오래가는 팀워크와 같다고 생각했다. 몇 달 뒤에는 단점이 보이고 지루해졌다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit31","skills":["비교"],"why":"첫날의 설렘과 오래가는 팀워크는 서로 다르다. 하준은 둘을 같은 것으로 생각했다. 현대인도 처음의 뜨거운 감정과 오래가는 사랑을 같은 것으로 생각한다.\n근거: “셋째로 현대인은 멋진 상대를 만나 그에게 빠지는 것이 곧 사랑이라고 생각하기 때문에, 사랑에 처음 빠지는 순간 경험하는 격정적인 상태와 사랑이 지속되는 상태를 혼동한다.” “두 사람이 서로에 대해서 더 깊이 알게 될수록, 처음에 기적처럼 생겼던 친밀감은 갈수록 약화된다.” “시쳇말로 눈에서 콩깍지가 벗겨지면서 처음에 느꼈던 기대와 설렘 그리고 즐거움 대신에, 서로에 대한 실망과 환멸 그리고 권태감이 자리하게 된다.”\n8문단에서 확인할 수 있어요.","evidence":{"title":"입단 첫날의 설렘","statement":"하준은 첫날의 설렘과 오래가는 팀워크를 같은 것으로 생각했다. 처음의 뜨거운 감정과 오래가는 사랑을 같다고 여기는 모습과 닮았다.","explanation":"첫날의 설렘과 오래가는 팀워크는 서로 다르다. 하준은 둘을 같은 것으로 생각했다. 현대인도 처음의 뜨거운 감정과 오래가는 사랑을 같은 것으로 생각한다.\n근거: “셋째로 현대인은 멋진 상대를 만나 그에게 빠지는 것이 곧 사랑이라고 생각하기 때문에, 사랑에 처음 빠지는 순간 경험하는 격정적인 상태와 사랑이 지속되는 상태를 혼동한다.” “두 사람이 서로에 대해서 더 깊이 알게 될수록, 처음에 기적처럼 생겼던 친밀감은 갈수록 약화된다.” “시쳇말로 눈에서 콩깍지가 벗겨지면서 처음에 느꼈던 기대와 설렘 그리고 즐거움 대신에, 서로에 대한 실망과 환멸 그리고 권태감이 자리하게 된다.”\n8문단에서 확인할 수 있어요.","valid":["R08:1","R08:4","R08:5"],"sources":[{"id":"R08","title":"에리히 프롬의 『사랑의 기술』 읽기","label":"8문단","sentences":[{"id":"R08:1","text":"셋째로 현대인은 멋진 상대를 만나 그에게 빠지는 것이 곧 사랑이라고 생각하기 때문에, 사랑에 처음 빠지는 순간 경험하는 격정적인 상태와 사랑이 지속되는 상태를 혼동한다.","paragraph":0,"memberIds":["R08:1"],"topic":"셋째, 현대인은 멋진 상대에게 빠지는 것이 곧 사랑이라고 생각한다. 그래서 처음 빠졌을 때의 뜨겁게 들뜬(격정적인) 상태와, 사랑이 오래 이어지는(지속되는) 상태를 헷갈린다(혼동한다)."},{"id":"R08:2","text":"두 연인 사이에 있던 벽이 갑자기 허물어지면서 두 사람이 완전히 하나가 된 것처럼 느끼는 상태야말로 우리가 맛볼 수 있는 가장 황홀한 기분이다.","paragraph":0,"memberIds":["R08:2"],"topic":"두 사람 사이의 벽이 갑자기 무너지고, 완전히 하나가 된 것처럼 느끼는 상태가 있다. 이것이야말로 우리가 느낄 수 있는 가장 황홀한 기분이다."},{"id":"R08:3","text":"그러나 이런 사랑은 오래 지속될 수 없다.","paragraph":0,"memberIds":["R08:3"],"topic":"그러나 이런 사랑은 오래갈 수 없다."},{"id":"R08:4","text":"두 사람이 서로에 대해서 더 깊이 알게 될수록, 처음에 기적처럼 생겼던 친밀감은 갈수록 약화된다.","paragraph":0,"memberIds":["R08:4"],"topic":"두 사람이 서로를 더 깊이 알게 될수록, 처음에 기적처럼 생긴 가까운 느낌(친밀감)은 점점 약해진다."},{"id":"R08:5","text":"시쳇말로 눈에서 콩깍지가 벗겨지면서 처음에 느꼈던 기대와 설렘 그리고 즐거움 대신에, 서로에 대한 실망과 환멸 그리고 권태감이 자리하게 된다.","paragraph":0,"memberIds":["R08:5"],"topic":"흔히 하는 말로 '눈에 씐 콩깍지가 벗겨지면' 처음의 기대·설렘·즐거움은 사라진다. 그 자리에 서로에 대한 실망, 환멸(기대가 깨져 싫어지는 마음), 권태감(지루하고 싫증 나는 느낌)이 들어선다."}]}]},"examplePractice":true,"id":"U31-E03-B1","type":"ox","answer":"O","changed":"하준은 첫날의 설렘과 오래가는 팀워크를 같은 것으로 생각했다. 처음의 뜨거운 감정과 오래가는 사랑을 같다고 여기는 모습과 닮았다.","ask":"다음 설명이 지문과 새 예시에 맞으면 O, 다르면 X를 고르세요.","highlightEvidence":true,"requiresEvidence":false,"editorSourceVersion":"6e0bb2d5158066b659c6bc4f4fd3a30e966c1705e24fec34128aae1be5f47a9b"}]},{"name":"U31-E03-B2 · 비교","items":[{"paragraphCount":2,"readingLabel":"8문단 · 새 예시 적용","sourceLabel":"에리히 프롬의 『사랑의 기술』 읽기 · 8문단","passage":"[에리히 프롬의 『사랑의 기술』 읽기 · 8문단]\n셋째로 현대인은 멋진 상대를 만나 그에게 빠지는 것이 곧 사랑이라고 생각하기 때문에, 사랑에 처음 빠지는 순간 경험하는 격정적인 상태와 사랑이 지속되는 상태를 혼동한다. 두 연인 사이에 있던 벽이 갑자기 허물어지면서 두 사람이 완전히 하나가 된 것처럼 느끼는 상태야말로 우리가 맛볼 수 있는 가장 황홀한 기분이다. 그러나 이런 사랑은 오래 지속될 수 없다. 두 사람이 서로에 대해서 더 깊이 알게 될수록, 처음에 기적처럼 생겼던 친밀감은 갈수록 약화된다. 시쳇말로 눈에서 콩깍지가 벗겨지면서 처음에 느꼈던 기대와 설렘 그리고 즐거움 대신에, 서로에 대한 실망과 환멸 그리고 권태감이 자리하게 된다.\n\n[이해를 돕는 새 예시 · 원문 사례 아님]\n하준은 입단 첫날의 설렘을 오래가는 팀워크와 같다고 생각했다. 몇 달 뒤에는 단점이 보이고 지루해졌다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit31","skills":["비교"],"why":"첫날의 설렘과 오래가는 팀워크는 서로 다르다. 하준은 둘을 같은 것으로 생각했다. 현대인도 처음의 뜨거운 감정과 오래가는 사랑을 같은 것으로 생각한다.\n근거: “셋째로 현대인은 멋진 상대를 만나 그에게 빠지는 것이 곧 사랑이라고 생각하기 때문에, 사랑에 처음 빠지는 순간 경험하는 격정적인 상태와 사랑이 지속되는 상태를 혼동한다.” “두 사람이 서로에 대해서 더 깊이 알게 될수록, 처음에 기적처럼 생겼던 친밀감은 갈수록 약화된다.” “시쳇말로 눈에서 콩깍지가 벗겨지면서 처음에 느꼈던 기대와 설렘 그리고 즐거움 대신에, 서로에 대한 실망과 환멸 그리고 권태감이 자리하게 된다.”\n8문단에서 확인할 수 있어요.","evidence":{"title":"입단 첫날의 설렘","statement":"하준은 첫날의 설렘과 오래가는 팀워크를 같은 것으로 생각했다. 처음의 뜨거운 감정과 오래가는 사랑을 같다고 여기는 모습과 닮았다.","explanation":"첫날의 설렘과 오래가는 팀워크는 서로 다르다. 하준은 둘을 같은 것으로 생각했다. 현대인도 처음의 뜨거운 감정과 오래가는 사랑을 같은 것으로 생각한다.\n근거: “셋째로 현대인은 멋진 상대를 만나 그에게 빠지는 것이 곧 사랑이라고 생각하기 때문에, 사랑에 처음 빠지는 순간 경험하는 격정적인 상태와 사랑이 지속되는 상태를 혼동한다.” “두 사람이 서로에 대해서 더 깊이 알게 될수록, 처음에 기적처럼 생겼던 친밀감은 갈수록 약화된다.” “시쳇말로 눈에서 콩깍지가 벗겨지면서 처음에 느꼈던 기대와 설렘 그리고 즐거움 대신에, 서로에 대한 실망과 환멸 그리고 권태감이 자리하게 된다.”\n8문단에서 확인할 수 있어요.","valid":["R08:1","R08:4","R08:5"],"sources":[{"id":"R08","title":"에리히 프롬의 『사랑의 기술』 읽기","label":"8문단","sentences":[{"id":"R08:1","text":"셋째로 현대인은 멋진 상대를 만나 그에게 빠지는 것이 곧 사랑이라고 생각하기 때문에, 사랑에 처음 빠지는 순간 경험하는 격정적인 상태와 사랑이 지속되는 상태를 혼동한다.","paragraph":0,"memberIds":["R08:1"],"topic":"셋째, 현대인은 멋진 상대에게 빠지는 것이 곧 사랑이라고 생각한다. 그래서 처음 빠졌을 때의 뜨겁게 들뜬(격정적인) 상태와, 사랑이 오래 이어지는(지속되는) 상태를 헷갈린다(혼동한다)."},{"id":"R08:2","text":"두 연인 사이에 있던 벽이 갑자기 허물어지면서 두 사람이 완전히 하나가 된 것처럼 느끼는 상태야말로 우리가 맛볼 수 있는 가장 황홀한 기분이다.","paragraph":0,"memberIds":["R08:2"],"topic":"두 사람 사이의 벽이 갑자기 무너지고, 완전히 하나가 된 것처럼 느끼는 상태가 있다. 이것이야말로 우리가 느낄 수 있는 가장 황홀한 기분이다."},{"id":"R08:3","text":"그러나 이런 사랑은 오래 지속될 수 없다.","paragraph":0,"memberIds":["R08:3"],"topic":"그러나 이런 사랑은 오래갈 수 없다."},{"id":"R08:4","text":"두 사람이 서로에 대해서 더 깊이 알게 될수록, 처음에 기적처럼 생겼던 친밀감은 갈수록 약화된다.","paragraph":0,"memberIds":["R08:4"],"topic":"두 사람이 서로를 더 깊이 알게 될수록, 처음에 기적처럼 생긴 가까운 느낌(친밀감)은 점점 약해진다."},{"id":"R08:5","text":"시쳇말로 눈에서 콩깍지가 벗겨지면서 처음에 느꼈던 기대와 설렘 그리고 즐거움 대신에, 서로에 대한 실망과 환멸 그리고 권태감이 자리하게 된다.","paragraph":0,"memberIds":["R08:5"],"topic":"흔히 하는 말로 '눈에 씐 콩깍지가 벗겨지면' 처음의 기대·설렘·즐거움은 사라진다. 그 자리에 서로에 대한 실망, 환멸(기대가 깨져 싫어지는 마음), 권태감(지루하고 싫증 나는 느낌)이 들어선다."}]}]},"examplePractice":true,"id":"U31-E03-B2","type":"ox","answer":"X","changed":"하준은 첫날의 설렘과 오래가는 팀워크를 서로 다른 것으로 생각했다. 처음의 뜨거운 감정과 오래가는 사랑이 다름을 아는 모습과 닮았다.","ask":"다음 설명이 지문과 새 예시에 맞으면 O, 다르면 X를 고르세요.","highlightEvidence":true,"requiresEvidence":false,"claimEdits":[{"start":22,"end":28,"before":"서로 다른 ","after":"같은 "},{"start":55,"end":66,"before":"사랑이 다름을 아는 ","after":"사랑을 같다고 여기는 "}],"editorSourceVersion":"41a13813821cdf391e3db69fb6b2e91ab426ae6b42d24a4202522a37871a0b54"}]},{"name":"U31-E04-B1 · 비교","items":[{"paragraphCount":2,"readingLabel":"9문단 · 새 예시 적용","sourceLabel":"에리히 프롬의 『사랑의 기술』 읽기 · 9문단","passage":"[에리히 프롬의 『사랑의 기술』 읽기 · 9문단]\n프롬은 현대인이 사랑에 대해서 배울 필요가 없다고 생각하는 이유를 위와 같은 세 가지의 태도로 정리한다. 그러나 프롬은 사랑이 흔히 말하듯 즐겁고 흥분된 감정이 아니라 끊임없이 연마해야 하는 기술이라고 말한다. 어떤 기술을 익히기 위해서는 그 기술에 대해서 이론적으로 배우고 실습해야 한다. 사랑의 기술 역시 그것을 익히기 위해서는 성숙한 사랑이 무엇인지, 그리고 그러한 진정한 사랑을 하기 위해서는 어떻게 해야 하는지를 배우고 그대로 실천해야 한다.\n\n[이해를 돕는 새 예시 · 원문 사례 아님]\n하준은 패스의 원리를 영상으로 배운 다음 매일 벽에 공을 차며 연습한다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit31","skills":["비교"],"why":"영상으로 패스 원리를 배우는 것은 이론 공부다. 벽에 공을 차며 직접 해 보는 것은 실습이다. 사랑의 기술도 배우고 실천해야 익힐 수 있다.\n근거: “어떤 기술을 익히기 위해서는 그 기술에 대해서 이론적으로 배우고 실습해야 한다.” “사랑의 기술 역시 그것을 익히기 위해서는 성숙한 사랑이 무엇인지, 그리고 그러한 진정한 사랑을 하기 위해서는 어떻게 해야 하는지를 배우고 그대로 실천해야 한다.”\n9문단에서 확인할 수 있어요.","evidence":{"title":"패스의 원리와 연습","statement":"하준은 패스 원리를 배우고 직접 연습한다. 사랑의 기술을 배우고 실천하는 과정과 닮았다.","explanation":"영상으로 패스 원리를 배우는 것은 이론 공부다. 벽에 공을 차며 직접 해 보는 것은 실습이다. 사랑의 기술도 배우고 실천해야 익힐 수 있다.\n근거: “어떤 기술을 익히기 위해서는 그 기술에 대해서 이론적으로 배우고 실습해야 한다.” “사랑의 기술 역시 그것을 익히기 위해서는 성숙한 사랑이 무엇인지, 그리고 그러한 진정한 사랑을 하기 위해서는 어떻게 해야 하는지를 배우고 그대로 실천해야 한다.”\n9문단에서 확인할 수 있어요.","valid":["R09:3","R09:4"],"sources":[{"id":"R09","title":"에리히 프롬의 『사랑의 기술』 읽기","label":"9문단","sentences":[{"id":"R09:1","text":"프롬은 현대인이 사랑에 대해서 배울 필요가 없다고 생각하는 이유를 위와 같은 세 가지의 태도로 정리한다.","paragraph":0,"memberIds":["R09:1"],"topic":"프롬은 현대인이 사랑을 배울 필요가 없다고 생각하는 이유를, 앞의 세 가지 태도로 정리한다."},{"id":"R09:2","text":"그러나 프롬은 사랑이 흔히 말하듯 즐겁고 흥분된 감정이 아니라 끊임없이 연마해야 하는 기술이라고 말한다.","paragraph":0,"memberIds":["R09:2"],"topic":"그러나 프롬은 이렇게 말한다. 사랑은 흔히 말하는 것처럼 즐겁고 들뜬 감정이 아니다. 끊임없이 갈고닦아야(연마해야) 하는 기술이다."},{"id":"R09:3","text":"어떤 기술을 익히기 위해서는 그 기술에 대해서 이론적으로 배우고 실습해야 한다.","paragraph":0,"memberIds":["R09:3"],"topic":"어떤 기술이든 익히려면 그 기술을 이론으로 배우고, 직접 해 보며 연습해야(실습해야) 한다."},{"id":"R09:4","text":"사랑의 기술 역시 그것을 익히기 위해서는 성숙한 사랑이 무엇인지, 그리고 그러한 진정한 사랑을 하기 위해서는 어떻게 해야 하는지를 배우고 그대로 실천해야 한다.","paragraph":0,"memberIds":["R09:4"],"topic":"사랑의 기술도 마찬가지다. 익히려면 성숙한 사랑이 무엇인지, 그런 진짜 사랑을 하려면 어떻게 해야 하는지를 배워야 한다. 그리고 배운 그대로 실천해야 한다."}]}]},"examplePractice":true,"id":"U31-E04-B1","type":"ox","answer":"O","changed":"하준은 패스 원리를 배우고 직접 연습한다. 사랑의 기술을 배우고 실천하는 과정과 닮았다.","ask":"다음 설명이 지문과 새 예시에 맞으면 O, 다르면 X를 고르세요.","highlightEvidence":true,"requiresEvidence":false,"editorSourceVersion":"9439778db7373de0490e0c8cf56756775f7f9ec75b31ca96bfd5812743323b52"}]},{"name":"U31-E04-B2 · 비교","items":[{"paragraphCount":2,"readingLabel":"9문단 · 새 예시 적용","sourceLabel":"에리히 프롬의 『사랑의 기술』 읽기 · 9문단","passage":"[에리히 프롬의 『사랑의 기술』 읽기 · 9문단]\n프롬은 현대인이 사랑에 대해서 배울 필요가 없다고 생각하는 이유를 위와 같은 세 가지의 태도로 정리한다. 그러나 프롬은 사랑이 흔히 말하듯 즐겁고 흥분된 감정이 아니라 끊임없이 연마해야 하는 기술이라고 말한다. 어떤 기술을 익히기 위해서는 그 기술에 대해서 이론적으로 배우고 실습해야 한다. 사랑의 기술 역시 그것을 익히기 위해서는 성숙한 사랑이 무엇인지, 그리고 그러한 진정한 사랑을 하기 위해서는 어떻게 해야 하는지를 배우고 그대로 실천해야 한다.\n\n[이해를 돕는 새 예시 · 원문 사례 아님]\n하준은 패스의 원리를 영상으로 배운 다음 매일 벽에 공을 차며 연습한다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit31","skills":["비교"],"why":"영상으로 패스 원리를 배우는 것은 이론 공부다. 벽에 공을 차며 직접 해 보는 것은 실습이다. 사랑의 기술도 배우고 실천해야 익힐 수 있다.\n근거: “어떤 기술을 익히기 위해서는 그 기술에 대해서 이론적으로 배우고 실습해야 한다.” “사랑의 기술 역시 그것을 익히기 위해서는 성숙한 사랑이 무엇인지, 그리고 그러한 진정한 사랑을 하기 위해서는 어떻게 해야 하는지를 배우고 그대로 실천해야 한다.”\n9문단에서 확인할 수 있어요.","evidence":{"title":"패스의 원리와 연습","statement":"하준은 패스 원리를 배우고 직접 연습한다. 사랑의 기술을 배우고 실천하는 과정과 닮았다.","explanation":"영상으로 패스 원리를 배우는 것은 이론 공부다. 벽에 공을 차며 직접 해 보는 것은 실습이다. 사랑의 기술도 배우고 실천해야 익힐 수 있다.\n근거: “어떤 기술을 익히기 위해서는 그 기술에 대해서 이론적으로 배우고 실습해야 한다.” “사랑의 기술 역시 그것을 익히기 위해서는 성숙한 사랑이 무엇인지, 그리고 그러한 진정한 사랑을 하기 위해서는 어떻게 해야 하는지를 배우고 그대로 실천해야 한다.”\n9문단에서 확인할 수 있어요.","valid":["R09:3","R09:4"],"sources":[{"id":"R09","title":"에리히 프롬의 『사랑의 기술』 읽기","label":"9문단","sentences":[{"id":"R09:1","text":"프롬은 현대인이 사랑에 대해서 배울 필요가 없다고 생각하는 이유를 위와 같은 세 가지의 태도로 정리한다.","paragraph":0,"memberIds":["R09:1"],"topic":"프롬은 현대인이 사랑을 배울 필요가 없다고 생각하는 이유를, 앞의 세 가지 태도로 정리한다."},{"id":"R09:2","text":"그러나 프롬은 사랑이 흔히 말하듯 즐겁고 흥분된 감정이 아니라 끊임없이 연마해야 하는 기술이라고 말한다.","paragraph":0,"memberIds":["R09:2"],"topic":"그러나 프롬은 이렇게 말한다. 사랑은 흔히 말하는 것처럼 즐겁고 들뜬 감정이 아니다. 끊임없이 갈고닦아야(연마해야) 하는 기술이다."},{"id":"R09:3","text":"어떤 기술을 익히기 위해서는 그 기술에 대해서 이론적으로 배우고 실습해야 한다.","paragraph":0,"memberIds":["R09:3"],"topic":"어떤 기술이든 익히려면 그 기술을 이론으로 배우고, 직접 해 보며 연습해야(실습해야) 한다."},{"id":"R09:4","text":"사랑의 기술 역시 그것을 익히기 위해서는 성숙한 사랑이 무엇인지, 그리고 그러한 진정한 사랑을 하기 위해서는 어떻게 해야 하는지를 배우고 그대로 실천해야 한다.","paragraph":0,"memberIds":["R09:4"],"topic":"사랑의 기술도 마찬가지다. 익히려면 성숙한 사랑이 무엇인지, 그런 진짜 사랑을 하려면 어떻게 해야 하는지를 배워야 한다. 그리고 배운 그대로 실천해야 한다."}]}]},"examplePractice":true,"id":"U31-E04-B2","type":"ox","answer":"X","changed":"하준은 설레는 감정만 있으면 패스 기술도 저절로 완성된다고 생각한다.","ask":"다음 설명이 지문과 새 예시에 맞으면 O, 다르면 X를 고르세요.","highlightEvidence":true,"requiresEvidence":false,"claimEdits":[{"start":4,"end":16,"before":"설레는 감정만 있으면 ","after":""},{"start":19,"end":38,"before":"기술도 저절로 완성된다고 생각한다.","after":"원리를 배우고 직접 연습한다. 사랑의 기술을 배우고 실천하는 과정과 닮았다."}],"editorSourceVersion":"c682226653a9519ddd8b2309127f354edc92486ebf163017650a41ef7e1bdbea"}]},{"name":"U31-P11-02-B1 · 비교","items":[{"paragraphCount":1,"readingLabel":"11문단","sourceLabel":"에리히 프롬의 『사랑의 기술』 읽기 · 11문단","passage":"[에리히 프롬의 『사랑의 기술』 읽기 · 11문단]\n우리는 흔히 사람들이 주는 것보다 받는 것을 더 좋아할 것이라고 생각한다. 그러나 사실은 그렇지 않다. 우리는 주는 데서 큰 기쁨을 맛본다. 물질의 영역에서 준다는 것은 자신이 부자임을 의미한다. 많이 가진 자가 부자가 아니라 많이 베푸는 자가 부자다. 조금이라도 잃어버릴까 걱정하는 자는 아무리 많이 갖고 있더라도 가난한 자다. 우리는 사람들에게 물질뿐만 아니라 자신의 기쁨, 관심, 지식, 유머 등을 줄 수 있다. 이렇게 줌으로써 우리는 다른 사람의 생명을 밝고 충만하게 만든다. 그리고 그렇게 다른 사람의 삶이 밝아지고 충만해지는 것을 보면서 우리도 더욱 밝아지고 충만해진다. 따라서 사랑을 준다는 것은 다른 사람도 주는 자로 만드는 것이며, 두 사람 모두가 더욱 큰 생명력을 갖게 되는 관계에 참여하는 것을 의미한다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit31","skills":["비교"],"why":"여기서 '부자'는 가진 물건의 양으로 정하지 않는다. 다른 사람에게 많이 베풀 수 있는 사람을 가리킨다.\n근거: “많이 가진 자가 부자가 아니라 많이 베푸는 자가 부자다.” “조금이라도 잃어버릴까 걱정하는 자는 아무리 많이 갖고 있더라도 가난한 자다.”\n11문단에서 확인할 수 있어요.","evidence":{"title":"부자는 많이 베푸는 자이다.","statement":"글쓴이는 많이 가진 사람보다 남에게 많이 베푸는 사람을 진정한 부자라고 본다.","explanation":"여기서 '부자'는 가진 물건의 양으로 정하지 않는다. 다른 사람에게 많이 베풀 수 있는 사람을 가리킨다.\n근거: “많이 가진 자가 부자가 아니라 많이 베푸는 자가 부자다.” “조금이라도 잃어버릴까 걱정하는 자는 아무리 많이 갖고 있더라도 가난한 자다.”\n11문단에서 확인할 수 있어요.","valid":["R11:5","R11:6"],"sources":[{"id":"R11","title":"에리히 프롬의 『사랑의 기술』 읽기","label":"11문단","sentences":[{"id":"R11:1","text":"우리는 흔히 사람들이 주는 것보다 받는 것을 더 좋아할 것이라고 생각한다.","paragraph":0,"memberIds":["R11:1"],"topic":"우리는 보통 사람들이 주는 것보다 받는 것을 더 좋아할 거라고 생각한다."},{"id":"R11:2","text":"그러나 사실은 그렇지 않다.","paragraph":0,"memberIds":["R11:2"],"topic":"그러나 사실은 그렇지 않다."},{"id":"R11:3","text":"우리는 주는 데서 큰 기쁨을 맛본다.","paragraph":0,"memberIds":["R11:3"],"topic":"우리는 줄 때 큰 기쁨을 맛본다."},{"id":"R11:4","text":"물질의 영역에서 준다는 것은 자신이 부자임을 의미한다.","paragraph":0,"memberIds":["R11:4"],"topic":"돈이나 물건(물질)을 준다는 것은 내가 부자라는 뜻이다."},{"id":"R11:5","text":"많이 가진 자가 부자가 아니라 많이 베푸는 자가 부자다.","paragraph":0,"memberIds":["R11:5"],"topic":"많이 가진 사람이 부자가 아니라, 많이 나눠 주는(베푸는) 사람이 부자다."},{"id":"R11:6","text":"조금이라도 잃어버릴까 걱정하는 자는 아무리 많이 갖고 있더라도 가난한 자다.","paragraph":0,"memberIds":["R11:6"],"topic":"조금이라도 잃을까 봐 걱정하는 사람은 아무리 많이 가졌어도 가난한 사람이다."},{"id":"R11:7","text":"우리는 사람들에게 물질뿐만 아니라 자신의 기쁨, 관심, 지식, 유머 등을 줄 수 있다.","paragraph":0,"memberIds":["R11:7"],"topic":"우리는 다른 사람에게 돈이나 물건뿐 아니라 내 기쁨, 관심, 지식, 유머 같은 것도 줄 수 있다."},{"id":"R11:8","text":"이렇게 줌으로써 우리는 다른 사람의 생명을 밝고 충만하게 만든다.","paragraph":0,"memberIds":["R11:8"],"topic":"이렇게 주면서 우리는 다른 사람의 생명(삶)을 밝고 가득 차게(충만하게) 만든다."},{"id":"R11:9","text":"그리고 그렇게 다른 사람의 삶이 밝아지고 충만해지는 것을 보면서 우리도 더욱 밝아지고 충만해진다.","paragraph":0,"memberIds":["R11:9"],"topic":"그리고 다른 사람의 삶이 밝아지고 가득 차는 것을 보면서, 우리도 더 밝아지고 가득 차게 된다."},{"id":"R11:10","text":"따라서 사랑을 준다는 것은 다른 사람도 주는 자로 만드는 것이며, 두 사람 모두가 더욱 큰 생명력을 갖게 되는 관계에 참여하는 것을 의미한다.","paragraph":0,"memberIds":["R11:10"],"topic":"그러니 사랑을 준다는 것은 상대도 '주는 사람'으로 만드는 일이다. 그리고 두 사람 모두 더 큰 활기(생명력)를 갖게 되는 관계에 함께하는(참여하는) 일이다."}]}]},"id":"U31-P11-02-B1","type":"ox","answer":"O","changed":"글쓴이는 많이 가진 사람보다 남에게 많이 베푸는 사람을 진정한 부자라고 본다.","ask":"다음 설명이 지문과 같으면 O, 다르면 X를 고르세요.","requiresEvidence":false,"highlightEvidence":true,"editorSourceVersion":"5072b9d59a690cf78a1424fb66c39c9a60422ad52d340483714b3282c83c2982"}]},{"name":"U31-P11-02-B2 · 비교","items":[{"paragraphCount":1,"readingLabel":"11문단","sourceLabel":"에리히 프롬의 『사랑의 기술』 읽기 · 11문단","passage":"[에리히 프롬의 『사랑의 기술』 읽기 · 11문단]\n우리는 흔히 사람들이 주는 것보다 받는 것을 더 좋아할 것이라고 생각한다. 그러나 사실은 그렇지 않다. 우리는 주는 데서 큰 기쁨을 맛본다. 물질의 영역에서 준다는 것은 자신이 부자임을 의미한다. 많이 가진 자가 부자가 아니라 많이 베푸는 자가 부자다. 조금이라도 잃어버릴까 걱정하는 자는 아무리 많이 갖고 있더라도 가난한 자다. 우리는 사람들에게 물질뿐만 아니라 자신의 기쁨, 관심, 지식, 유머 등을 줄 수 있다. 이렇게 줌으로써 우리는 다른 사람의 생명을 밝고 충만하게 만든다. 그리고 그렇게 다른 사람의 삶이 밝아지고 충만해지는 것을 보면서 우리도 더욱 밝아지고 충만해진다. 따라서 사랑을 준다는 것은 다른 사람도 주는 자로 만드는 것이며, 두 사람 모두가 더욱 큰 생명력을 갖게 되는 관계에 참여하는 것을 의미한다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit31","skills":["비교"],"why":"여기서 '부자'는 가진 물건의 양으로 정하지 않는다. 다른 사람에게 많이 베풀 수 있는 사람을 가리킨다.\n근거: “많이 가진 자가 부자가 아니라 많이 베푸는 자가 부자다.” “조금이라도 잃어버릴까 걱정하는 자는 아무리 많이 갖고 있더라도 가난한 자다.”\n11문단에서 확인할 수 있어요.","evidence":{"title":"부자는 많이 베푸는 자이다.","statement":"글쓴이는 많이 가진 사람보다 남에게 많이 베푸는 사람을 진정한 부자라고 본다.","explanation":"여기서 '부자'는 가진 물건의 양으로 정하지 않는다. 다른 사람에게 많이 베풀 수 있는 사람을 가리킨다.\n근거: “많이 가진 자가 부자가 아니라 많이 베푸는 자가 부자다.” “조금이라도 잃어버릴까 걱정하는 자는 아무리 많이 갖고 있더라도 가난한 자다.”\n11문단에서 확인할 수 있어요.","valid":["R11:5","R11:6"],"sources":[{"id":"R11","title":"에리히 프롬의 『사랑의 기술』 읽기","label":"11문단","sentences":[{"id":"R11:1","text":"우리는 흔히 사람들이 주는 것보다 받는 것을 더 좋아할 것이라고 생각한다.","paragraph":0,"memberIds":["R11:1"],"topic":"우리는 보통 사람들이 주는 것보다 받는 것을 더 좋아할 거라고 생각한다."},{"id":"R11:2","text":"그러나 사실은 그렇지 않다.","paragraph":0,"memberIds":["R11:2"],"topic":"그러나 사실은 그렇지 않다."},{"id":"R11:3","text":"우리는 주는 데서 큰 기쁨을 맛본다.","paragraph":0,"memberIds":["R11:3"],"topic":"우리는 줄 때 큰 기쁨을 맛본다."},{"id":"R11:4","text":"물질의 영역에서 준다는 것은 자신이 부자임을 의미한다.","paragraph":0,"memberIds":["R11:4"],"topic":"돈이나 물건(물질)을 준다는 것은 내가 부자라는 뜻이다."},{"id":"R11:5","text":"많이 가진 자가 부자가 아니라 많이 베푸는 자가 부자다.","paragraph":0,"memberIds":["R11:5"],"topic":"많이 가진 사람이 부자가 아니라, 많이 나눠 주는(베푸는) 사람이 부자다."},{"id":"R11:6","text":"조금이라도 잃어버릴까 걱정하는 자는 아무리 많이 갖고 있더라도 가난한 자다.","paragraph":0,"memberIds":["R11:6"],"topic":"조금이라도 잃을까 봐 걱정하는 사람은 아무리 많이 가졌어도 가난한 사람이다."},{"id":"R11:7","text":"우리는 사람들에게 물질뿐만 아니라 자신의 기쁨, 관심, 지식, 유머 등을 줄 수 있다.","paragraph":0,"memberIds":["R11:7"],"topic":"우리는 다른 사람에게 돈이나 물건뿐 아니라 내 기쁨, 관심, 지식, 유머 같은 것도 줄 수 있다."},{"id":"R11:8","text":"이렇게 줌으로써 우리는 다른 사람의 생명을 밝고 충만하게 만든다.","paragraph":0,"memberIds":["R11:8"],"topic":"이렇게 주면서 우리는 다른 사람의 생명(삶)을 밝고 가득 차게(충만하게) 만든다."},{"id":"R11:9","text":"그리고 그렇게 다른 사람의 삶이 밝아지고 충만해지는 것을 보면서 우리도 더욱 밝아지고 충만해진다.","paragraph":0,"memberIds":["R11:9"],"topic":"그리고 다른 사람의 삶이 밝아지고 가득 차는 것을 보면서, 우리도 더 밝아지고 가득 차게 된다."},{"id":"R11:10","text":"따라서 사랑을 준다는 것은 다른 사람도 주는 자로 만드는 것이며, 두 사람 모두가 더욱 큰 생명력을 갖게 되는 관계에 참여하는 것을 의미한다.","paragraph":0,"memberIds":["R11:10"],"topic":"그러니 사랑을 준다는 것은 상대도 '주는 사람'으로 만드는 일이다. 그리고 두 사람 모두 더 큰 활기(생명력)를 갖게 되는 관계에 함께하는(참여하는) 일이다."}]}]},"id":"U31-P11-02-B2","type":"ox","answer":"X","changed":"글쓴이는 남에게 많이 베푸는 사람보다 많이 쌓아 두기만 하는 사람을 진정한 부자라고 본다.","ask":"다음 설명이 지문과 같으면 O, 다르면 X를 고르세요.","requiresEvidence":false,"highlightEvidence":true,"claimEdits":[{"start":0,"end":5,"before":"글쓴이는 ","after":"글쓴이는 많이 가진 사람보다 "},{"start":16,"end":34,"before":"사람보다 많이 쌓아 두기만 하는 ","after":""}],"editorSourceVersion":"6e443b0755cc9cb1942d191146a85a15b32a1569e1c54750430a0c98bcff4247"}]},{"name":"U31-H10-01-B1 · 스스로 행동하는 사랑","items":[{"paragraphCount":1,"readingLabel":"10문단 · 핵심 읽기 1/5단계","sourceLabel":"에리히 프롬의 『사랑의 기술』 읽기 · 10문단","passage":"[핵심 문장 · 10문단]\n성숙한 사랑은 수동적 감정이 아니라 능동적인 활동이다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit31","skills":["비교"],"why":"그저 감정을 느끼는 것이 아니라 직접 행동하는 사랑이다.\n근거: “성숙한 사랑은 수동적 감정이 아니라 능동적인 활동이다.”","evidence":{"title":"스스로 행동하는 사랑","statement":"성숙한 사랑은 스스로 적극적으로 하는 활동이다.","explanation":"그저 감정을 느끼는 것이 아니라 직접 행동하는 사랑이다.\n근거: “성숙한 사랑은 수동적 감정이 아니라 능동적인 활동이다.”","valid":["R10:1"],"sources":[{"id":"R10","title":"에리히 프롬의 『사랑의 기술』 읽기","label":"10문단","sentences":[{"id":"R10:1","text":"성숙한 사랑은 수동적 감정이 아니라 능동적인 활동이다.","paragraph":0,"memberIds":["R10:1"],"topic":"성숙한 사랑은 저절로 생겨서 당하는(수동적) 감정이 아니다. 내가 스스로 하는(능동적) 활동이다."}]}]},"shortComparison":true,"focusQuotes":[{"id":"R10:1","text":"성숙한 사랑은 수동적 감정이 아니라 능동적인 활동이다."}],"highlightEvidence":true,"requiresEvidence":false,"id":"U31-H10-01-B1","type":"ox","answer":"O","changed":"성숙한 사랑은 스스로 적극적으로 하는 활동이다.","ask":"형광펜 문장을 읽고, 다음 설명이 맞으면 O, 틀리면 X를 고르세요.","progressiveComparison":true,"progressiveStep":1,"progressiveTotal":5,"progressiveLabel":"핵심 낱말과 사실","learningFocus":"스스로 행동하는 사랑","hintGuide":"가만히 느끼기만 하는지, 스스로 행동하는지 보세요.","synthesis":false,"editorSourceVersion":"b5ce7bd19cfb20614367e447a700a6c9c4192730aff337d849f7fac9ebdbf152"}]}]};})(window);
